function ok = tf_plot3d_begin()
    PsychImGui('NewFrame', tf_input());
    PsychImGui('Begin', 'genplot3dw', [], 1024);
    ok = PsychImGui('ImPlot3D.BeginPlot', 'genplot3d', [300 200]);
end

function tf_plot3d_end(ok)
    if ok
        PsychImGui('ImPlot3D.EndPlot');
    end
    PsychImGui('End');
    PsychImGui('Render');
end

function ok = tf_plot_begin()
    PsychImGui('NewFrame', tf_input());
    PsychImGui('Begin', 'genplotw', [], 1024);
    ok = PsychImGui('ImPlot.BeginPlot', 'genplot', [300 200]);
end

function tf_plot_end(ok)
    if ok
        PsychImGui('ImPlot.EndPlot');
    end
    PsychImGui('End');
    PsychImGui('Render');
end

function tf_begin()
    PsychImGui('NewFrame', tf_input());
    % ImGuiWindowFlags_MenuBar, so the menu bar subcommands are legal.
    PsychImGui('Begin', 'genw', [], 1024);
end

function tf_end()
    PsychImGui('End');
    PsychImGui('Render');
end

function ok(name, cond)
    global TST_PASS TST_FAIL %#ok<GVMIS>
    if cond
        TST_PASS = TST_PASS + 1;
    else
        TST_FAIL = TST_FAIL + 1;
        fprintf(2, '  FAIL  %s\n', name);
    end
end
